from abc import ABCMeta, abstractmethod

from .bip.classical_gnb import ClassicalGnbBipLogFileProvider
from .bip.cloud_gnb import CloudGnbBipLogFileProvider
from .emil.classical_gnb import ClassicalGnbEmilLogFileProvider
from .emil.cloud_gnb import CloudGnbEmilLogFileProvider
from .log_file_provider_strategy import LogFileProviderStrategy
from .snapshot.gnb import GnbSnapshotLogfileProvider
from .syslog.classical_gnb import ClassicalGnbSyslogLogfileProvider
from .syslog.cloud_gnb import CloudGnbSyslogLogfileProvider
from .uplane_trace.classical_gnb import ClassicalGnbUplaneTraceLogFileProvider
from .uplane_trace.cloud_gnb import CloudGnbUplaneTraceLogFileProvider
from .screl.gnb import GnbScrelLogfileProvider


class GnbLogFileProviderStrategy(LogFileProviderStrategy, metaclass=ABCMeta):
    @abstractmethod
    def get_bip_log_file(self, log_directory, collector_config):
        pass

    @abstractmethod
    def get_emil_log_file(self, log_directory, collector_config):
        pass

    @abstractmethod
    def get_snapshot_log_file(self, log_directory, collector_config):
        pass

    @abstractmethod
    def get_syslog_log_file(self, log_directory, collector_config):
        pass

    @abstractmethod
    def get_uplane_trace_log_file(self, log_directory, collector_config):
        pass

    @abstractmethod
    def get_screl_log_file(self, log_directory, collector_config):
        pass


class ClassicalGnbLogFileProviderStrategy(
        ClassicalGnbBipLogFileProvider,
        ClassicalGnbEmilLogFileProvider,
        GnbSnapshotLogfileProvider,
        ClassicalGnbSyslogLogfileProvider,
        ClassicalGnbUplaneTraceLogFileProvider,
        GnbScrelLogfileProvider,
        GnbLogFileProviderStrategy):
    pass


class CloudGnbLogFileProviderStrategy(
        CloudGnbBipLogFileProvider,
        CloudGnbEmilLogFileProvider,
        GnbSnapshotLogfileProvider,
        CloudGnbSyslogLogfileProvider,
        CloudGnbUplaneTraceLogFileProvider,
        GnbScrelLogfileProvider,
        GnbLogFileProviderStrategy):
    pass
